import{G as e,W as t,n,rt as r}from"./chunks/framework.9o07hMZQ.js";var i=JSON.parse(`{"title":"X-Plane 11/12 連線教程","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/tutorial/xplane.md","filePath":"zh-TW/tutorial/xplane.md","lastUpdated":0}`),a={name:`zh-TW/tutorial/xplane.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="x-plane-11-12-連線教程" tabindex="-1">X-Plane 11/12 連線教程 <a class="header-anchor" href="#x-plane-11-12-連線教程" aria-label="Permalink to “X-Plane 11/12 連線教程”">​</a></h1><p>本教程適用於 X-Plane 11 與 X-Plane 12，介紹如何連入 XFLYSIM 連飛伺服器。</p><h2 id="準備階段" tabindex="-1">準備階段 <a class="header-anchor" href="#準備階段" aria-label="Permalink to “準備階段”">​</a></h2><h3 id="_1-安裝飛行模擬軟體" tabindex="-1">1. 安裝飛行模擬軟體 <a class="header-anchor" href="#_1-安裝飛行模擬軟體" aria-label="Permalink to “1. 安裝飛行模擬軟體”">​</a></h3><ul><li>透過 Steam 或 Laminar Research 官網購買並安裝 X-Plane 11 / 12。</li><li>建議更新至最新版本，保證與連飛客戶端相容。</li></ul><h3 id="_2-安裝連飛客戶端" tabindex="-1">2. 安裝連飛客戶端 <a class="header-anchor" href="#_2-安裝連飛客戶端" aria-label="Permalink to “2. 安裝連飛客戶端”">​</a></h3><ul><li>下載並安裝 XFLYSIM 連飛客戶端。</li><li>在客戶端中填寫連飛網站註冊的賬號與呼號。</li></ul><h3 id="_3-安裝語音軟體" tabindex="-1">3. 安裝語音軟體 <a class="header-anchor" href="#_3-安裝語音軟體" aria-label="Permalink to “3. 安裝語音軟體”">​</a></h3><ul><li>語音機組需要安裝 <strong>XVoice</strong> 語音軟體（詳見 <a href="/tutorial/xvoice.html">XVoice 語音教程</a>）。</li><li>文字機組可跳過此步驟，在遊戲內直接使用文字交流。</li></ul><h2 id="連線步驟" tabindex="-1">連線步驟 <a class="header-anchor" href="#連線步驟" aria-label="Permalink to “連線步驟”">​</a></h2><ol><li>開啟 X-Plane，選擇需要飛行的機型和機場。</li><li>將飛機停放在<strong>固定停機位</strong>，等待載入完成。</li><li>啟動連飛客戶端，填入呼號並連線伺服器 <code>ol.xflysim.com</code>。</li><li>連線成功後，第一時間提交飛行計劃（起降機場、巡航高度層、計劃航路、機型等）。</li><li>在未提供管制服務的空域，使用公用頻率 122.800；有管制員線上時聽從其指揮。</li></ol><h2 id="注意事項" tabindex="-1">注意事項 <a class="header-anchor" href="#注意事項" aria-label="Permalink to “注意事項”">​</a></h2><ul><li>嚴禁在滑行道、跑道上等非停機位直接連線。</li><li>飛行前請仔細閱讀<a href="/rules.html">使用者準則</a>。</li><li>管制空域內注意收聽管制員指令，遵守&quot;左窗避讓原則&quot;。</li></ul>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};